"""Offline protocol regression checks; no account or network access."""
import gzip
import json
import struct
import unittest
import zlib
from unittest.mock import patch

from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
import protocol as probe


class ResponseDecoderTests(unittest.TestCase):
    def test_request_frames_match_fixed_spt_csharp_vectors(self):
        # Generated by unmodified f6c19b2a ShuffleInPlace and checked with its
        # DeShuffleAsync, in work/eft-spt-request-validation-20261020/.
        fixtures = [
            (bytes.fromhex("78da030000000001"), "00080300000100007800000000dada780003"),
            (zlib.compress(b'{"completed":true}', 9),
             "004951ceabcf2d2dc878ad4a4d1a06da2a4a2905404dce00abb2e978da0049f4002a5656"),
        ]
        for payload, expected in fixtures:
            with self.subTest(payload=payload):
                self.assertEqual(probe.frame_request(payload).hex(), expected)

    def test_request_frame_rejects_invalid_size_and_padding(self):
        for payload, padding in [(b"", 6), ("not bytes", 6), (b"x", 5), (b"x", 17), (b"x", True)]:
            with self.subTest(payload=payload, padding=padding), self.assertRaises(ValueError):
                probe.frame_request(payload, padding)
        with patch.object(probe, "MAX_BYTES", 10), self.assertRaises(ValueError):
            probe.frame_request(b"x")

    @staticmethod
    def frame(payload):
        data = bytearray(struct.pack("<i", len(payload)) + payload + bytes(13))
        start = len(data) % 0xAAB
        for index in range(len(data) - 1, 0, -1):
            swap = ((1624453 * (0x65F6D + start + index) + 1023920427) % 0x8ED7A18D) % index
            data[index], data[swap] = data[swap], data[index]
        return bytes(data)

    def test_framed_encrypted_success_after_http_gzip(self):
        payload = {"err": 0, "data": {"locations": {"woods": {"BossLocationSpawn": []}}}}
        compressed = zlib.compress(json.dumps(payload).encode())
        count = 16 - len(compressed) % 16
        iv = bytes(range(16))
        encryptor = Cipher(algorithms.AES(probe.CLIENT_AES_KEY), modes.CBC(iv)).encryptor()
        encrypted = iv + encryptor.update(compressed + bytes([count]) * count) + encryptor.finalize()
        decoded, codec, _ = probe.decoded_json(
            gzip.compress(self.frame(encrypted)), {"x-encryption": "aes", "content-encoding": "gzip"})
        self.assertEqual(decoded, payload)
        self.assertEqual(codec, "framed+aes-cbc+zlib")

    def test_framing_does_not_accept_random_data_or_skip_bound(self):
        with self.assertRaises(ValueError):
            probe.unframe_response(bytes(64))
        with patch.object(probe, "MAX_BYTES", 64):
            with self.assertRaises(ValueError):
                probe.decoded_json(bytes(65), {"x-encryption": "aes"})
        decoded, _, _ = probe.decoded_json(self.frame(bytes(32)), {"x-encryption": "aes"})
        self.assertIsNone(decoded)

    def test_encrypted_compressed_error_preserves_business_code(self):
        payload = {"err": 1000, "errmsg": "1000 - wrong encryption params", "data": None}
        compressed = zlib.compress(json.dumps(payload).encode())
        padded = compressed + b"\0" * (-len(compressed) % 16)
        iv = bytes(range(16))
        encryptor = Cipher(algorithms.AES(probe.CLIENT_AES_KEY), modes.CBC(iv)).encryptor()
        body = iv + encryptor.update(padded) + encryptor.finalize()
        decoded, codec, _ = probe.decoded_json(
            gzip.compress(body), {"x-encryption": "aes", "content-encoding": "gzip"})
        self.assertEqual(decoded, payload)
        self.assertEqual(codec, "aes-cbc+zlib")

    def test_opaque_locations_length_does_not_become_auth_failure(self):
        decoded, codec, _ = probe.decoded_json(bytes(260785), {"x-encryption": "aes"})
        self.assertIsNone(decoded)
        self.assertEqual(codec, "encrypted-unsupported-length")

    def test_live_error_pkcs7_padding_shape(self):
        payload = {"err": 1000, "errmsg": "1000 - wrong encryption params", "data": None}
        compressed = zlib.compress(json.dumps(payload, separators=(",", ":")).encode())
        count = 16 - len(compressed) % 16
        iv = bytes(range(16))
        encryptor = Cipher(algorithms.AES(probe.CLIENT_AES_KEY), modes.CBC(iv)).encryptor()
        body = iv + encryptor.update(compressed + bytes([count]) * count) + encryptor.finalize()
        decoded, codec, _ = probe.decoded_json(body, {"x-encryption": "aes"})
        self.assertEqual(decoded, payload)
        self.assertEqual(codec, "aes-cbc+zlib")

    def test_expansion_limit_enforced(self):
        with patch.object(probe, "MAX_BYTES", 64):
            with self.assertRaises(ValueError):
                probe.inflate_bounded(zlib.compress(b"a" * 2048))

    def test_unknown_cipher_not_treated_as_plaintext(self):
        decoded, codec, _ = probe.decoded_json(b'{"err":0}', {"x-encryption": "unknown"})
        self.assertIsNone(decoded)
        self.assertEqual(codec, "encrypted-unsupported-algorithm")

    def test_compression_corruption_and_trailing_data_rejected(self):
        for raw in [zlib.compress(b"{}")[:-2], zlib.compress(b"{}") + b"junk"]:
            with self.subTest(size=len(raw)), self.assertRaises(ValueError):
                probe.inflate_bounded(raw)


if __name__ == "__main__":
    unittest.main()
